// Generated by `just generate` from `src/plugins/dotclaude/slices/spec/domain/validate.ts`. Edit the source and run `just generate`.
// The checks of the Markdown formats of the spec store.
// Each check gives the issues that it finds, and an empty list when none.
// Plain data and pure functions only.

import type {
  CapabilitySpec,
  DeltaFile,
  Package,
  Requirement,
  Task,
} from "./formats.ts";
import { PACKAGE_SECTIONS } from "./formats.ts";

export type IssueRule =
  | "requirement.no-shall"
  | "requirement.no-scenario"
  | "scenario.no-when"
  | "scenario.no-then"
  | "delta.name-repeated"
  | "task.no-verify"
  | "task.duplicate-id"
  | "package.empty-field"
  | "package.empty-section"
  | "package.owns-empty"
  | "package.owns-wildcard"
  | "package.owns-plugins"
  | "plan.duplicate-id"
  | "plan.dep-missing"
  | "plan.dep-cycle"
  | "wave.owns-overlap";

/** One failed check, with the rule that it broke and the name of the item that broke it. */
export interface Issue {
  rule: IssueRule;
  subject: string;
  message: string;
}

const issue = (rule: IssueRule, subject: string, message: string): Issue => ({
  rule,
  subject,
  message,
});

const WILDCARD = /[*?[\]{}]/;

export const validateRequirement = (req: Requirement): Issue[] => {
  const issues: Issue[] = [];
  if (!/\bSHALL\b/.test(req.text)) {
    issues.push(
      issue("requirement.no-shall", req.name, "the requirement has no SHALL"),
    );
  }
  if (req.scenarios.length === 0) {
    issues.push(
      issue(
        "requirement.no-scenario",
        req.name,
        "the requirement has no scenario",
      ),
    );
  }
  for (const scenario of req.scenarios) {
    if (!scenario.whenLines.some((c) => c !== "")) {
      issues.push(
        issue(
          "scenario.no-when",
          scenario.name,
          "the scenario has no WHEN line",
        ),
      );
    }
    if (!scenario.thenLines.some((c) => c !== "")) {
      issues.push(
        issue(
          "scenario.no-then",
          scenario.name,
          "the scenario has no THEN line",
        ),
      );
    }
  }
  return issues;
};

export const validateSpec = (spec: CapabilitySpec): Issue[] =>
  spec.requirements.flatMap(validateRequirement);

/** Checks the requirements of a delta, and that one name is in one section only. */
export const validateDelta = (delta: DeltaFile): Issue[] => {
  const names = [
    ...delta.added.map((r) => r.name),
    ...delta.modified.map((r) => r.name),
    ...delta.removed,
  ];
  const repeated = names.filter((n, i) => names.indexOf(n) !== i);
  return [
    ...delta.added.flatMap(validateRequirement),
    ...delta.modified.flatMap(validateRequirement),
    ...[...new Set(repeated)].map((n) =>
      issue("delta.name-repeated", n, "the name is in two sections"),
    ),
  ];
};

export const validateTasks = (tasks: Task[]): Issue[] => {
  const issues: Issue[] = [];
  tasks.forEach((task, i) => {
    if (!task.verify) {
      issues.push(
        issue("task.no-verify", task.id, "the task has no Verify line"),
      );
    }
    if (tasks.findIndex((t) => t.id === task.id) !== i) {
      issues.push(issue("task.duplicate-id", task.id, "the id is repeated"));
    }
  });
  return issues;
};

/** Checks one package: its front matter, its sections, and its `owns` entries. */
export const validatePackage = (pkg: Package): Issue[] => {
  const { front, sections } = pkg;
  const id = front.id;
  const issues: Issue[] = [];
  for (const [field, value] of [
    ["id", front.id],
    ["verify", front.verify],
    ["agent", front.agent],
  ] as const) {
    if (value === "") {
      issues.push(issue("package.empty-field", id, `\`${field}\` is empty`));
    }
  }
  for (const name of PACKAGE_SECTIONS) {
    if (sections[name] === "") {
      issues.push(
        issue("package.empty-section", id, `section \`${name}\` is empty`),
      );
    }
  }
  if (front.owns.length === 0 || front.owns.some((o) => o === "")) {
    issues.push(issue("package.owns-empty", id, "`owns` has an empty entry"));
  }
  for (const entry of front.owns) {
    if (WILDCARD.test(entry)) {
      issues.push(
        issue("package.owns-wildcard", id, `\`${entry}\` has a wildcard`),
      );
    }
    if (entry === "plugins" || entry.startsWith("plugins/")) {
      issues.push(
        issue("package.owns-plugins", id, `\`${entry}\` is under plugins`),
      );
    }
  }
  return issues;
};

/** Checks the ids and the deps of all packages: no repeated id, no missing dep, and no cycle. */
export const validateDeps = (packages: Package[]): Issue[] => {
  const issues: Issue[] = [];
  const ids = packages.map((p) => p.front.id);
  const known = new Set(ids);
  for (const id of known) {
    if (ids.indexOf(id) !== ids.lastIndexOf(id)) {
      issues.push(issue("plan.duplicate-id", id, "the id is repeated"));
    }
  }
  for (const pkg of packages) {
    for (const dep of pkg.front.deps) {
      if (!known.has(dep)) {
        issues.push(
          issue(
            "plan.dep-missing",
            pkg.front.id,
            `dep \`${dep}\` does not exist`,
          ),
        );
      }
    }
  }
  for (const id of cycleMembers(packages)) {
    issues.push(issue("plan.dep-cycle", id, "the package is in a dep cycle"));
  }
  return issues;
};

/** The ids of the packages on a dep cycle, found by a depth-first walk of the deps. */
const cycleMembers = (packages: Package[]): string[] => {
  const deps = new Map<string, string[]>();
  for (const pkg of packages) {
    deps.set(pkg.front.id, pkg.front.deps);
  }
  const state = new Map<string, "visiting" | "done">();
  const stack: string[] = [];
  const members = new Set<string>();
  const visit = (id: string): void => {
    const seen = state.get(id);
    if (seen === "done") {
      return;
    }
    if (seen === "visiting") {
      for (const member of stack.slice(stack.indexOf(id))) {
        members.add(member);
      }
      return;
    }
    state.set(id, "visiting");
    stack.push(id);
    for (const dep of deps.get(id) ?? []) {
      if (deps.has(dep)) {
        visit(dep);
      }
    }
    stack.pop();
    state.set(id, "done");
  };
  for (const id of deps.keys()) {
    visit(id);
  }
  return [...members];
};

/**
 * Checks that no two packages of one wave own overlapping paths.
 * The caller passes the open packages of one wave, because the lanes and the
 * waves live in `events.jsonl`, outside this domain.
 * Two entries overlap when one is a prefix of the other.
 */
export const validateWave = (packages: Package[]): Issue[] =>
  packages.flatMap((a, i) =>
    packages
      .slice(i + 1)
      .filter((b) => ownsOverlap(a.front.owns, b.front.owns))
      .map((b) =>
        issue(
          "wave.owns-overlap",
          `${a.front.id} ${b.front.id}`,
          "the owns entries overlap",
        ),
      ),
  );

const ownsOverlap = (a: string[], b: string[]): boolean =>
  a.some((x) => b.some((y) => x.startsWith(y) || y.startsWith(x)));
